    buy_book = []  # (price, arrival_time, id, remaining_qty)
    sell_book = []  # (price, arrival_time, id, remaining_qty)
    order_map = {}  # id -> (side, index_in_book, original_arrival_time)
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, book_idx, _ = order_map[order_id]
                if side == 'buy':
                    if book_idx < len(buy_book) and buy_book[book_idx][2] == order_id:
                        price, arr_time, oid, qty = buy_book[book_idx]
                        buy_book[book_idx] = (price, arr_time, oid, 0)
                else:
                    if book_idx < len(sell_book) and sell_book[book_idx][2] == order_id:
                        price, arr_time, oid, qty = sell_book[book_idx]
                        sell_book[book_idx] = (price, arr_time, oid, 0)
                del order_map[order_id]

        elif order[0] == 'limit':
            _, order_id, side, price, qty = order
            remaining = qty

